  Widget build(BuildContext context) {
    final vm = ref.watch(swapVmProvider);
    final s = vm.state;

    final fromSymbol = vm.fromSymbol;
    final toSymbol = vm.toSymbol;

    final estOut = s.estReceive;
    // currentMinOut = estOut ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â (1 ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¹ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ slippage), already computed in VM.
    final minOut = vm.currentMinOut ?? 0.0;

    return wrapAnim(
      child: _SheetShell(
        children: [
          _Header(
            icon: LucideIcons.arrowLeftRight,
            title: 'Confirm Swap',
            subtitle: 'Review your transaction',
          ),
          const SizedBox(height: 20),
          _SwapVisualization(
            from: '${widget.fmt.format(vm.amount)} $fromSymbol',
            to: estOut != null
                ? '${widget.fmt.format(estOut)} $toSymbol'
                : 'Calculating...',
          ),
          const SizedBox(height: 20),
          _DetailsCard(
            rows: [
              _DetailRow(
                label: 'Slippage Tolerance',
                value: _fmtPct(vm.slippagePct),
                icon: LucideIcons.zap,
              ),
              _DetailRow(
                label: 'Minimum Received',
                value: '${widget.fmt.format(minOut)} $toSymbol',
                icon: LucideIcons.shield,
                highlight: true,
              ),
              _DetailRow(
                label: 'Network Fee',
                value: vm.hasFeeEstimates
                    ? '~ ${widget.fmt.format(vm.estCombinedFeeXlm)} XLM'
                    : 'Calculating...',
                icon: LucideIcons.coins,
                subtitle: s.needsTrustline ? 'Includes trustline setup' : null,
              ),
            ],
          ),
          const SizedBox(height: 24),
          _ActionRow(
            onCancel: () => closeSheet<double?>(null),
            confirmLabel: 'Confirm Swap',
            onConfirm: () => closeSheet<double?>(minOut),
          ),
        ],
      ),
    );
  }
}

