  final String confirmLabel;
  final VoidCallback onConfirm;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Expanded(
          child: CustomButton(
            type: ButtonType.outlined,
            icon: LucideIcons.x,
            text: 'Cancel',
            onPressed: onCancel,
          ),
        ),
        const SizedBox(width: 12),
        Expanded(
          flex: 2,
          child: CustomButton(
            icon: LucideIcons.checkCircle2,
            text: confirmLabel,
            onPressed: onConfirm,
          ),
        ),
      ],
    );
  }
}

